                placeholder="Search cardsâ€¦"
                size="small"
                slotProps={{
                    htmlInput: { 'aria-label': 'Search project', readOnly: true },
                    input: {
                        endAdornment: (
                            <InputAdornment position="end">
                                <Box
                                    component="span"
                                    sx={{
                                        border: 1,
                                        borderColor: 'divider',
                                        borderRadius: 0.5,
                                        color: 'text.disabled',
                                        fontSize: 10.5,
                                        lineHeight: 1.4,
